import { queryClient } from '@/app/query/queryClient';
import { supabase } from '@/shared/utils/supabase';
import { DbWeightLog } from '@/shared/types/supabase';
import { authService } from '@/features/auth/services/authService';
import { profileService } from '@/features/profile/services/profileService';
import { calculateBodyFat } from '@/shared/utils/navyMethod';

export const weightService = {
  async getWeightLogs(): Promise<DbWeightLog[]> {
    const userId = await authService.getUserId();
    const { data, error } = await supabase
      .from('weight_logs')
      .select('*')
      .eq('user_id', userId)
      .order('date', { ascending: true });
      
    if (error) {
      console.error('Error fetching weight logs:', error);
      throw error;
    }
    return data || [];
  },

  async addWeightLog(logData: Omit<DbWeightLog, 'id' | 'user_id' | 'body_fat'>, measurementsUpdated: boolean = false): Promise<DbWeightLog | null> {
    const [userId, profile] = await Promise.all([
      authService.getUserId(),
      queryClient.getQueryData<any>(['profile']) || queryClient.fetchQuery({ queryKey: ['profile'], queryFn: () => profileService.getProfile() })
    ]);
    
    let bodyFatEstimate = undefined;
    
    // Auto-calculate body fat if measurements exist
    if (measurementsUpdated && profile && profile.height && profile.waist && profile.neck) {
      const rawEstimate = calculateBodyFat(
        profile.gender,
        profile.height,
        profile.waist,
        profile.neck,
        profile.hip
      );
      bodyFatEstimate = Math.max(3, Math.min(60, Math.round(rawEstimate * 10) / 10));
    }
    
    const payload = {
      ...logData,
      body_fat: bodyFatEstimate,
      user_id: userId,
    };

    // Check if an entry for this local date already exists
    const datePrefix = logData.date.substring(0, 10);
    
    const { data: existing } = await supabase
      .from('weight_logs')
      .select('id')
      .eq('user_id', userId)
      .eq('date', datePrefix)
      .limit(1)
      .maybeSingle();

    let data, error;
    if (existing && existing.id) {
      // Update existing
      const res = await supabase
        .from('weight_logs')
        .update(payload)
        .eq('id', existing.id)
        .select()
        .maybeSingle();
      data = res.data;
      error = res.error;
    } else {
      // Insert new
      const res = await supabase
        .from('weight_logs')
        .insert(payload)
        .select()
        .maybeSingle();
      data = res.data;
      error = res.error;
    }

    if (error && error.code !== 'PGRST116') {
      console.error('Error adding weight log:', error);
      throw error;
    }

    const returnedData = data || payload;

    // Update profile weight and goal body fat if calculated
    if (profile) {
      const promises: Promise<any>[] = [
        profileService.updateProfile({ weight: logData.weight })
      ];
      if (bodyFatEstimate) {
        promises.push(supabase.from("goals").update({ current_bf: bodyFatEstimate }).eq("user_id", userId) as any);
      }
      await Promise.all(promises);
    }
    
    return returnedData;
  }
};
